import * as React from 'react';
import { MenuPosition } from '..';
import { CommonProps } from '../utility/commonProps';
export type Items = '5' | '10' | '15' | '20';
export type PageType = string | number;
export interface PaginationProps extends CommonProps {
    /**
     * Current selected page
     * @default 1
     */
    currentPage?: PageType;
    /**
     * Hide count displaying items per page
     * @default false
     */
    hideItemsPerPageCount?: boolean;
    /**
     * Hide dropdown displaying items per page
     * @default false
     */
    hideItemsPerPageDropdown?: boolean;
    /**
     * Number of items to show per page
     * @default '5'
     */
    itemsPerPage?: Items;
    /**
     *
     * Position of the items per page dropdown
     *
     * @default 'bottomLeft
     */
    itemsPerPageMenuPosition?: MenuPosition;
    /**
     *
     * Callback function when items per page is changed
     */
    onItemsPerPageChange?: (value: Items) => void;
    /**
     * Callback function when current page is changed
     */
    setCurrentPage: (value: PageType) => void;
    /**
     * Total number of items
     *
     * @default 0
     */
    totalItemCount: number;
    /**
     * Set size of the pagination icon buttons
     *
     * @default 'medium'
     */
    size?: 'small' | 'medium' | 'large';
    /**
     * The id for the pagination.
     */
    id?: string;
}
/**
 * The pagination component enables the user to select a specific page from a range of pages.
 * Pagination is used in conjunction with a data table to view additional rows in the table, spread across multiple pages.
 *
 * ### Content
 *
 * The pagination component accepts the total count of the table items and calculates the number of pages based on that count.
 * The page number and items to be displayed on the page are sent to the callback function to perform necessary operations.
 * It also accepts two boolean props for hiding the items per page count and the items per page dropdown.
 *
 * ```tsx
 * import * as React from "react";
 * import { Pagination } from "@walmart-dataventures/shared-components";
 *
 * export default () => {
 *  return (
 *    <Pagination
          currentPage={1}
          hideItemsPerPageCount
          hideItemsPerPageDropdown
          itemsPerPage={'5'}
          onItemsPerPageChange={(value) => { console.log('Do something with the selected value from dropdown', value)}}
          setCurrentPage={(value) => { console.log('Do something with the current page value', value)}}
          totalItemCount={50}
      />
 *  )
 * }
 *
 * ```
 *
 * ### Features
 *
 * ### Variants
 *
 * Pagination comes with four variants:
 *
 * - Default: All pagination elements are visible by default, such as: Items per page dropdown, count and pagination view
 * - Items per page & Pagination: The items per page count is hidden in this variant
 * - Total item count & Pagination: The items per page dropdown is hidden in this variant
 * - Pagination only: Items per page dropdown and count are hidden in this variant
 *
 * See code snippets in the stories below for implementation details on different variants.
 *
 * Pagination with ellipsis
 *
 * Page number display with ellipsis is implemented via an algorithm automatically.
 * The algorithm ensures that first and last boundary of pages is always displayed, along with 2 page numbers before and after the current selected page.
 */
export declare const Pagination: React.FC<PaginationProps>;
